CREATE TABLE "TicketTier" ("id" TEXT NOT NULL PRIMARY KEY, "tourId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "perks" TEXT, "imageUrl" TEXT, "price" REAL NOT NULL, "quantity" INTEGER NOT NULL, "sold" INTEGER NOT NULL DEFAULT 0, "perOrderLimit" INTEGER, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "TicketTier_tourId_fkey" FOREIGN KEY ("tourId") REFERENCES "Tour" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Order" ("id" TEXT NOT NULL PRIMARY KEY, "reference" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL, "tourId" TEXT NOT NULL, "buyerName" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT NOT NULL, "notes" TEXT, "currency" TEXT NOT NULL, "amount" REAL NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "paymentStatus" TEXT NOT NULL DEFAULT 'PENDING', "paymentRef" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Order_tourId_fkey" FOREIGN KEY ("tourId") REFERENCES "Tour" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL PRIMARY KEY, "orderId" TEXT NOT NULL, "ticketTierId" TEXT NOT NULL, "tierName" TEXT NOT NULL, "unitPrice" REAL NOT NULL, "quantity" INTEGER NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "OrderItem_ticketTierId_fkey" FOREIGN KEY ("ticketTierId") REFERENCES "TicketTier" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "NotificationLog" ("id" TEXT NOT NULL PRIMARY KEY, "orderId" TEXT NOT NULL, "channel" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "deliveredAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "NotificationLog_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
PRAGMA defer_foreign_keys=ON;
PRAGMA foreign_keys=OFF;
CREATE TABLE "new_Tour" ("id" TEXT NOT NULL PRIMARY KEY, "date" TEXT NOT NULL, "dateTime" DATETIME, "city" TEXT NOT NULL, "venue" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'TICKETS', "ticketType" TEXT NOT NULL DEFAULT 'DEFAULT', "ticketImage" TEXT, "ticketTiers" TEXT, "ticketingEnabled" BOOLEAN NOT NULL DEFAULT true, "ticketMode" TEXT NOT NULL DEFAULT 'PLATFORM_DEFAULT', "currency" TEXT NOT NULL DEFAULT 'NGN', "saleStartsAt" DATETIME, "saleEndsAt" DATETIME, "perOrderLimit" INTEGER NOT NULL DEFAULT 6, "soldOutMessage" TEXT DEFAULT 'This show is currently sold out.', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
INSERT INTO "new_Tour" ("city", "createdAt", "date", "dateTime", "id", "status", "ticketImage", "ticketTiers", "ticketType", "updatedAt", "venue") SELECT "city", "createdAt", "date", "dateTime", "id", "status", "ticketImage", "ticketTiers", "ticketType", "updatedAt", "venue" FROM "Tour";
DROP TABLE "Tour";
ALTER TABLE "new_Tour" RENAME TO "Tour";
PRAGMA foreign_keys=ON;
PRAGMA defer_foreign_keys=OFF;
CREATE UNIQUE INDEX "Order_reference_key" ON "Order"("reference");
CREATE UNIQUE INDEX "Order_idempotencyKey_key" ON "Order"("idempotencyKey");
